'use strict';
// Colour is an optional redundant teaching prompt, never a required answer signal.
const readingColourMap=Object.freeze({b:'#244f91',d:'#9c431c',p:'#19635a',q:'#663d8b',g:'#663d8b',m:'#244f91',n:'#9c431c',u:'#19635a',t:'#244f91',f:'#9c431c',v:'#663d8b',w:'#663d8b'});
let readingDisplay={colour:true};try{const savedDisplay=JSON.parse(localStorage.getItem('spotmatch-reading-display-v1')||'null');if(savedDisplay&&typeof savedDisplay.colour==='boolean')readingDisplay.colour=savedDisplay.colour;}catch{}
function readingColour(letter){if(!readingDisplay.colour||readingState&&readingGame(readingState.id)?.mode==='puppet-program')return '#345b47';return readingColourMap[String(letter).toLowerCase()]||'#345b47';}
function readingPaint(text){return [...String(text)].map(c=>`<span class="reading-ink" style="color:${readingColour(c)}">${readingEscape(c)}</span>`).join('');}
const readingSoundPairs={p:'b',b:'p',d:'t',t:'d',v:'f',f:'v'};
const readingLetterDetails={b:'Tall stem on the left; rounded part on the right.',d:'Tall stem on the right; rounded part on the left.',p:'Descending stem on the left.',q:'Descending stem on the right.',m:'Two arches.',n:'One arch, open below.',u:'A low curve, open above.',w:'Two low points; the strokes meet below.'};
function readingMorePaths(letter){const oval='M35 66C35 30 85 30 85 66C85 103 35 103 35 66';return {b:['M35 14V101',oval],d:['M85 14V101',oval],p:['M35 39V128',oval],q:['M85 39V128',oval],m:['M20 100V40','M20 53Q41 21 55 53V100','M55 53Q81 21 94 53V100'],n:['M27 100V40','M27 54Q63 20 87 54V100'],u:['M27 40V76Q27 114 87 86V40','M87 40V100'],w:['M17 40L36 100L59 63L82 100L103 40']}[letter]||[];}
function readingDetailSvg(letter,partial=false){const paths=readingMorePaths(letter),ink=readingColour(letter);return `<svg viewBox="0 0 120 145" aria-hidden="true"><g fill="none" stroke-linecap="round" stroke-linejoin="round">${paths.map((d,i)=>`<path d="${d}" stroke="${partial&&i>0?'#dce2d5':ink}" stroke-width="11"/>`).join('')}</g></svg>`;}
function readingLetterDetail(letter){return `<div class="reading-letter-detail">${readingDetailSvg(letter)}<p>${readingLetterDetails[letter]||'Compare the complete printed form.'}</p></div>`;}
function readingMoreControls(){const wp=wordPlayControls();if(wp!==null)return wp;const plain=readingGame(readingState.id).mode==='puppet-program';return `<div class="reading-display-option"><label><input id="readingColourToggle" type="checkbox" ${readingDisplay.colour&&!plain?'checked':''} ${plain?'disabled':''}><span>${plain?'Plain-print practice':'Letter colour cues'}</span></label><small>${plain?'Compare the shapes; adult help remains welcome.':'Optional. The letter shapes carry the same information.'}</small></div>`;}
function readingMorePrepare(){if(wordPlayPrepare())return;if(readingAdventurePrepare())return;const s=readingState,g=readingGame(s.id);s.showDetail=false;const mode=g.mode;
 if(mode==='edge-letter'){const[word,position]=s.item.split(':');s.word=readingWord(word);s.edge=position==='first'?0:s.word.tiles.length-1;}
 if(mode==='ending-build'){const[base,target]=s.item.split('>');s.base=base;s.word=readingWord(target);}
 if(mode==='order-words'){s.word={word:s.item,tiles:s.item.split(' '),picture:''};s.bank=[...s.word.tiles,...['dog','sits.','cat','naps.'].filter(w=>!s.word.tiles.includes(w)).slice(0,2)];const n=(s.round+s.seed+1)%s.bank.length;s.bank=s.bank.slice(n).concat(s.bank.slice(0,n));s.slots=s.word.tiles.map(()=>null);}
}
function readingMoreCue(){const wp=wordPlayCue();if(wp!==null)return wp;const adventure=readingAdventureCue();if(adventure!==null)return adventure;const s=readingState,g=readingGame(s.id);if(!g.extended)return null;
 if(['shape-build','arch-match'].includes(g.mode))return `${g.adult} This example is ${s.item}. ${readingLetterDetails[s.item]||''}`;
 if(g.mode==='sound-neighbour'){const example={p:'pan',d:'dog',v:'van'}[s.item];return `${g.adult} Say the sound at the start of “${example}”. Its taught letter is ${s.item}. Model first, then close this cue before the child chooses.`;}
 if(g.mode==='edge-letter')return `${g.adult} Word: ${s.word.word}. Compare the ${s.edge===0?'first':'final'} spelling, ${s.word.tiles[s.edge]}.`;
 if(g.mode==='ending-build')return `${g.adult} This example changes ${s.base} to ${s.word.word}.`;
 if(g.mode==='word-proof')return `${g.adult} The intended word is “${s.item}”. Say it naturally, then model its sounds if helpful.`;
 if(g.mode==='order-words')return `${g.adult} The intended sentence is “${s.item}”. The child can ask for the printed model.`;
 return `${g.adult} This example: “${s.item}”.`;
}
function readingCurveSvg(side){return `<svg viewBox="0 0 120 145" aria-hidden="true"><path d="M60 30V115" stroke="#d5ddcf" stroke-width="10" stroke-linecap="round"/><ellipse cx="${side==='left'?35:85}" cy="67" rx="24" ry="30" fill="none" stroke="#486d63" stroke-width="11"/></svg>`;}
function readingMoreTrain(word,tiles){return `<div class="reading-train-engine" aria-hidden="true"><svg viewBox="0 0 170 100"><path d="M18 42H106V78H18Z" fill="#8faeab"/><path d="M89 18H142V78H89Z" fill="#d8af6f"/><rect x="98" y="27" width="34" height="29" rx="4" fill="#e9f0db"/><path d="M38 42V20H58V42M28 18H68" fill="#7c9697" stroke="#6c8586" stroke-width="5"/><circle cx="44" cy="80" r="16" fill="#617c80"/><circle cx="116" cy="80" r="16" fill="#617c80"/><path d="M4 97H164" stroke="#bdac8b" stroke-width="3"/></svg></div><p class="reading-small">One place for every sound. Keep adjacent consonants separate.</p><div class="reading-train-word" aria-label="${readingEscape(word)}">${tiles.map(t=>`<span>${readingPaint(t)}</span>`).join('')}</div>`;}
function readingMoreChallenge(){const wp=wordPlayChallenge();if(wp!==null)return wp;const adventure=readingAdventureChallenge();if(adventure!==null)return adventure;const s=readingState,g=readingGame(s.id),mode=g.mode;if(!g.extended)return null;let prompt='',body='';
 if(mode==='shape-build'){prompt='Robot found a stem. Add the rounded part.';body=`<div class="reading-repair-model" data-reading-home="choice"><b>${readingPaint(s.item)}</b>${readingDetailSvg(s.item,true)}</div><div class="reading-options">${readingOptions(s.item==='b'||s.item==='p'?'right':'left',['left','right']).map(side=>`<button class="reading-choice reading-curve" data-reading-choice="${side}" aria-label="Rounded part on the ${side}">${readingCurveSvg(side)}</button>`).join('')}</div>`;}
 else if(mode==='arch-match'){prompt='Which printed letter belongs in this arch-shaped garage?';body=`<div class="reading-garage-model" data-reading-home="choice">${readingDetailSvg(s.item)}</div><button class="back" id="readingLetterLens">${s.showDetail?'Hide the detail':'Show the detail'}</button>${s.showDetail?`<p class="reading-small">${readingLetterDetails[s.item]}</p>`:''}`+readingButtons(readingOptions(s.item,(s.item==='m'||s.item==='w'?['m','w','n']:['n','u','m']).filter(c=>c!==s.item)),s.item);}
 else if(mode==='sound-neighbour'){prompt='Listen to your grown-up. Which letter carries that sound?';body='<div class="reading-listen" data-reading-home="choice">Listen, then send a letter to the gate.</div>'+readingButtons(readingOptions(s.item,[readingSoundPairs[s.item]]),s.item);}
 else if(mode==='edge-letter'){prompt=`Who rides at the ${s.edge===0?'front':'back'} of this word?`;body=`<div class="reading-edge-word" data-reading-home="choice">${s.word.tiles.map((t,i)=>`<span class="${i===s.edge?'reading-edge-focus':''}">${readingPaint(t)}</span>`).join('')}</div>`+readingButtons(readingOptions(s.word.tiles[s.edge],s.word.tiles),s.word.tiles[s.edge]);}
 else if(mode==='cluster-build'){prompt='Load every sound onto the express train.';body='<div class="reading-cluster">'+readingMoreTrain('Ready to load',[])+readingTileUI(mode)+'</div>';}
 else if(mode==='ending-build'){prompt='One is becoming more than one. Add the word ending.';body=`<div class="reading-ending-word" data-reading-home="choice"><b>${readingPaint(s.base)}</b><span class="reading-ending-place" aria-label="Ending place">＋</span></div>`+readingButtons(readingOptions('s',['t','p']),'s');}
 else if(mode==='order-words'){prompt='Put the message carriages in order.';body=`<button class="back" id="readingSentenceHint">${s.showDetail?'Hide the message model':'Show the message model'}</button>${s.showDetail?`<p class="reading-word-model">${readingPaint(s.item)}</p>`:''}<div class="reading-word-carriages">${readingTileUI(mode)}</div>`;}
 else if(mode==='sentence-meaning'){prompt='Read together. Which little scene fits the whole caption?';body=`<div class="reading-big-word" data-reading-home="choice">${readingPaint(s.item)}</div><div class="reading-options reading-caption-options">${readingOptions(s.item,['cat on mat','cat in bag','hat on cat'].filter(c=>c!==s.item)).map(c=>`<button class="reading-choice" data-reading-choice="${c}" aria-label="Scene: ${c}">${readingDirectorArt(c)}</button>`).join('')}</div>`;}
 else if(mode==='word-proof'){prompt='Robot meant the word your grown-up says. Repair his label.';const wrong={bed:'bad',dog:'dig',pin:'pan'}[s.item],others={bed:['bad','bid'],dog:['dig','log'],pin:['pan','pen']}[s.item];body=`<div class="reading-robot-label" data-reading-home="choice"><span>Robot printed:</span><del>${readingPaint(wrong)}</del></div>`+readingButtons(readingOptions(s.item,others),s.item,'letter','reading-word-choice');}
 return `<h2 class="reading-invitation" tabindex="-1">${prompt}</h2>${body}`;
}
function readingMoreAnswer(){const s=readingState,g=readingGame(s.id);if(!g.extended)return null;if(g.mode==='shape-build')return ['b','p'].includes(s.item)?'right':'left';if(g.mode==='edge-letter')return s.word.tiles[s.edge];if(g.mode==='ending-build')return 's';return s.item;}
function readingMoreResult(){const wp=wordPlayResult();if(wp!==null)return wp;const adventure=readingAdventureResult();if(adventure!==null)return adventure;const s=readingState,g=readingGame(s.id);if(!g.extended)return null;const mode=g.mode;
 if(['shape-build','arch-match'].includes(mode))return readingDetailSvg(s.item);
 if(mode==='sound-neighbour')return `<span class="reading-result-letter">${readingPaint(s.item)}</span>`;
 if(mode==='cluster-build')return `<span class="reading-train-result">${readingMoreTrain(s.word.word,s.word.tiles)}</span>`;
 if(mode==='edge-letter')return `<span class="reading-result-edge">${s.word.tiles.map((t,i)=>`<span class="${i===s.edge?'reading-edge-focus':''}">${readingPaint(t)}</span>`).join('')}</span>`;
 if(mode==='ending-build'){const base=readingWord(s.base).picture;return `<span class="reading-plural-pictures">${readingPicture(base)}${readingPicture(base)}</span>`;}
 if(mode==='sentence-meaning')return readingDirectorArt(s.item);
 if(mode==='order-words')return readingActionArt(s.item.includes('naps')?'nap':s.item.includes('taps')?'tap':'sit',s.item.includes('dog')?'dog':'cat');
 if(mode==='word-proof')return readingPicture(s.word.picture);return '';
}
function readingMoreMessage(){const wp=wordPlayMessage();if(wp!==null)return wp;const adventure=readingAdventureMessage();if(adventure!==null)return adventure;const s=readingState,g=readingGame(s.id);if(!g.extended)return null;const mode=g.mode;if(mode==='arch-match')return `That shape fits ${s.item}!`;if(mode==='shape-build')return `Robot’s ${s.item} is back together!`;if(mode==='sound-neighbour')return `You chose ${s.item} for the gate!`;if(mode==='edge-letter')return `${s.word.tiles[s.edge]} rides at the ${s.edge===0?'front':'back'} of ${s.word.word}!`;if(mode==='cluster-build')return `All aboard! Our word is ${s.word.word}.`;if(mode==='ending-build')return `More than one: ${s.word.word}!`;if(mode==='order-words')return 'The message carriages are ready. Read them together!';if(mode==='sentence-meaning')return 'That scene fits the whole caption!';if(mode==='word-proof')return `Repaired! The label says ${s.word.word}.`;return null;}
function readingMoreBind(){if(wordPlayActive()){wordPlayBind();return;}readingAdventureBind();const s=readingState;if(!readingActive(s))return;const colour=app.querySelector('#readingColourToggle');if(colour)colour.onchange=()=>{readingDisplay.colour=colour.checked;try{localStorage.setItem('spotmatch-reading-display-v1',JSON.stringify(readingDisplay));}catch{}s.help=true;readingRender();app.querySelector('#readingColourToggle')?.focus({preventScroll:true});};
 const lens=app.querySelector('#readingLetterLens')||app.querySelector('#readingSentenceHint');if(lens)lens.onclick=()=>{if(!readingCanAct())return;s.showDetail=!s.showDetail;s.help=true;readingRender();};

}
function readingColourGuide(){return `<h3>Short-word adventures: choosing support</h3><p>Read all the spellings and blend the word before checking its picture. Twenty new activities connect print and meaning through fishing, packing, labels, dominoes, syllable trains, word changes, crosswords, word searches, pairs, categories, inventories, comics, painting, quantities, word locks, recipes, word spaces, bingo, mosaics and a syllable band. Each activity explains its particular support and adaptations. Start with two choices; three are optional. No speed, speech or handwriting is required.</p><p>For dyslexia or decoding difficulties, explicitly teach and model the relevant sound–spelling links. For language difficulties, check that the pictured words are understood first. For intellectual or broader developmental disabilities, model one small step and revisit it across days. For autistic children, preview the predictable goal and use the quieter board if useful. For attention difficulties, try a brief round and a break. For speech or motor difficulties, keep AAC, pointing, keyboard, tap and adult-entered responses available. Choose by the child’s needs rather than assuming every child with a diagnosis needs the same adaptation.</p><p>Syllable colours mark spoken chunks: dog has one syllable; nap|kin has two. The train is a supported next step, with a printed model; assembling it can be copying rather than independent reading. Letter-cue mode separately highlights b, d, p and g; plain print is also available. This colour scheme and these games have not been evaluated as a reading intervention. Their teaching rationale draws on the IES guide linked below, not evidence for a particular game or colour.</p><h3>Colour cues and commonly confused letters</h3><p>Colour is an optional, consistent teaching prompt in these activities. Printed shape, stem position and text remain available without it. The app’s colour scheme has not been shown to treat dyslexia or improve reading. Try it if useful, switch it off if distracting, and explore ordinary print with support still available. There is no requirement to name or distinguish colours.</p><p>Mixing up particular letters is a reason to teach those forms and their taught sounds; a reversal alone does not diagnose dyslexia. Compare b/d, p/q, m/n, u/n and m/w only when that comparison fits the child’s observed needs. English q is normally introduced with u; the shape activities do not teach an isolated q sound.</p><p>Other activities keep adjacent consonants separate, explore first/final spellings and plural endings, arrange word tiles, and connect captions with meaning. Introduce the relevant English spellings first. Model the different spoken endings of cats, cups and dogs rather than saying every written s makes /s/.</p><ul class="sen-sources">${readingSources.slice(8).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><p>${s.note}</p></li>`).join('')}</ul>`;}
